// XOR 後計算 1 的個數
// 時間複雜度: O(1)（最多 32 位），空間複雜度: O(1)
function hammingDistance(x, y) {
    let v = x ^ y, count = 0;
    while (v) {
        v &= v - 1; // 清掉最低位的 1
        count++;
    }
    return count;
}

solutions.python:
# 方法一：Brian Kernighan（推薦）
class Solution:
    def hammingDistance(self, x: int, y: int) -> int:
        xor = x ^ y
        count = 0
        while xor:
            xor &= xor - 1      # 每次消掉最右邊的 1
            count += 1
        return count


# 方法二：逐位檢查
class Solution:
    def hammingDistance(self, x: int, y: int) -> int:
        xor = x ^ y
        count = 0
        for i in range(32):
            count += (xor >> i) & 1
        return count


# 方法三：Python 內建
class Solution:
    def hammingDistance(self, x: int, y: int) -> int:
        return bin(x ^ y).count('1')

