// 方法一：Brian Kernighan（推薦）
class Solution {
public:
    int hammingDistance(int x, int y) {
        int xorVal = x ^ y, count = 0;
        while (xorVal) {
            xorVal &= (xorVal - 1);   // 消掉最右邊的 1
            count++;
        }
        return count;
    }
};

// 方法二：逐位移位比較
class Solution {
public:
    int hammingDistance(int x, int y) {
        int count = 0;
        while (x || y) {
            if ((x & 1) != (y & 1)) count++;
            x >>= 1;
            y >>= 1;
        }
        return count;
    }
};

// 方法三：內建指令
class Solution {
public:
    int hammingDistance(int x, int y) {
        return __builtin_popcount(x ^ y);
    }
};

